import org.junit.jupiter.params.provider.CsvSource;

class NativeTripleTermMatchingTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI S = VF.createIRI("urn:s");
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI O = VF.createIRI("urn:o");
	private static final TripleTerm TERM = VF.createTripleTerm(S, P, O);

	private static NativeTripleTermQueryEvaluationStep step(Source source, String s, String p, String o, String t) {
		return new NativeTripleTermQueryEvaluationStep(Var.of(s), Var.of(p), Var.of(o), Var.of(t), source,
				new QueryEvaluationContext.Minimal(null));
	}

	private static List<BindingSet> collect(CloseableIteration<BindingSet> rows) {
		try (rows) {
			List<BindingSet> result = new ArrayList<>();
			while (rows.hasNext()) {
				result.add(rows.next());
			}
			return result;
		}
	}

	@Test
	void boundWholeTermUsesAnExactLookupAndRetainsMembershipCheck() {
		Source source = new Source(List.of(TERM));
		var bindings = new MapBindingSet();
		bindings.addBinding("term", TERM);
		var evaluator = step(source, "s", "p", "o", "term");
		assertEquals(1, collect(evaluator.evaluate(bindings)).size());
		assertEquals(List.of(S, P, O), source.request);
		assertEquals(1, source.closes);
		bindings.setBinding("term", VF.createTripleTerm(S, P, VF.createIRI("urn:absent")));
		assertTrue(collect(evaluator.evaluate(bindings)).isEmpty());
	}

	@Test
	void incompatibleConstraintsAvoidTheSourceLookup() {
		Source source = new Source(List.of(TERM));
		var evaluator = step(source, "s", "p", "o", "term");
		for (String name : List.of("s", "p", "term")) {
			var bindings = new MapBindingSet();
			bindings.addBinding(name, VF.createLiteral("wrong type"));
			assertTrue(collect(evaluator.evaluate(bindings)).isEmpty());
		}
		var bindings = new MapBindingSet();
		bindings.addBinding("term", TERM);
		bindings.addBinding("s", O);
		assertTrue(collect(evaluator.evaluate(bindings)).isEmpty());
		assertEquals(0, source.lookups);
	}

	@ParameterizedTest
	@CsvSource({ "x,x,o,t", "x,p,x,t", "s,x,x,t", "x,x,x,t" })
	void repeatedComponentVariablesFilterBeforeBinding(String s, String p, String o, String t) {
		TripleTerm match = VF.createTripleTerm(S, S, S);
		Source source = new Source(List.of(TERM, match));
		var rows = collect(step(source, s, p, o, t).evaluate(EmptyBindingSet.getInstance()));
		assertEquals(1, rows.size());
		assertEquals(S, rows.get(0).getValue("x"));
		assertEquals(match, rows.get(0).getValue(t));
		assertEquals(1, source.closes);
	}

	@ParameterizedTest
	@CsvSource({ "x,p,o,x", "s,x,o,x", "s,p,x,x" })
	void aFiniteTermCannotEqualOneOfItsOwnComponents(String s, String p, String o, String t) {
		Source source = new Source(List.of(TERM));
		assertTrue(collect(step(source, s, p, o, t).evaluate(EmptyBindingSet.getInstance())).isEmpty());
	}

	private static final class Source implements NativeTripleTermSource {
		private final List<TripleTerm> terms;
		private List<Value> request;
		private int lookups;
		private int closes;

		Source(List<TripleTerm> terms) {
			this.terms = terms;
		}

		@Override
		public CloseableIteration<? extends TripleTerm> getTripleTerms(Resource s, IRI p, Value o) {
			lookups++;
			request = Arrays.asList(s, p, o);
			var matches = terms.stream()
					.filter(term -> (s == null || s.equals(term.getSubject()))
							&& (p == null || p.equals(term.getPredicate()))
							&& (o == null || o.equals(term.getObject())))
					.toList();
			return new CloseableIteratorIteration<>(matches.iterator()) {
				@Override
				protected void handleClose() {
					closes++;
				}
			};
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource s, IRI p, Value o, Resource... contexts) {
			return new EmptyIteration<>();
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}
}
